// Owned installed fixture / shared export behavior comparison; no source submission.
import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import {chromium} from 'playwright';import {load} from 'cheerio';import {renderedDocument} from '../../engine/form-appearance.mjs';import {extract} from '../../engine/extract.mjs';import {applyForms} from '../../scripts/form-export.mjs';import {applyComponents} from '../../scripts/component-export.mjs';
const record=JSON.parse(await readFile('work/wpf-heldout/mask-alias-record.json')),browser=await chromium.launch({channel:'chrome'}),cases=[];let sourcePosts=0;
async function exercise(page){const inputs=page.locator('.wpforms-masked-input');assert.equal(await inputs.count(),4);for(const [i,value]of ['20240229','person@example.test','1234','12.50'].entries())await inputs.nth(i).pressSequentially(value);const values=await inputs.evaluateAll(es=>es.map(e=>e.value));assert.deepEqual(values,['2024-02-29','person@example.test','1234','12.50']);await inputs.nth(0).fill('2023-02-29');const invalidDateResult=await inputs.nth(0).inputValue();assert.notEqual(invalidDateResult,'2023-02-29');return {values,invalidDateResult};}
try{for(const width of [1440,390]){const source=await browser.newPage({viewport:{width,height:844}});await source.route('**/*',r=>{if(!['GET','HEAD'].includes(r.request().method())){sourcePosts++;return r.abort();}return new URL(r.request().url()).origin==='http://127.0.0.1:9439'?r.continue():r.abort();});assert.equal((await source.goto(record.url,{waitUntil:'networkidle'})).status(),200);const model=extract(await renderedDocument(source),record.url),contract=model.sourceForms.find(f=>f.provider==='wpforms');assert.equal(contract.fields.filter(f=>f.inputMask).length,4);const expected=await exercise(source);await source.close();
 contract.delivery={endpoint:'/fixture-delivery',format:'json'};const $=load(model.content);applyForms($,model,[contract]);const scripts=applyComponents($);assert.ok(scripts.some(s=>s.id==='input-mask'));const exported=await browser.newPage({viewport:{width,height:844}});await exported.route('https://fixture.test/',r=>r.fulfill({contentType:'text/html',body:$.html()}));await exported.goto('https://fixture.test/');const actual=await exercise(exported);assert.deepEqual(actual,expected);cases.push({width,source:expected,exported:actual});await exported.close();}
assert.equal(sourcePosts,0);const result={definitionSHA256:createHash('sha256').update(JSON.stringify(record.definition)).digest('hex'),scope:'Installed source versus transformed captured-form behavior; not full native migration or visual assessment',cases,sourcePosts,aiCalls:0};await writeFile('artifacts/platform/wpforms-heldout/mask-alias-check.json',JSON.stringify(result,null,2));console.log(JSON.stringify({cases:cases.length,sourcePosts}));}finally{await browser.close();}
